import{_ as e,o as a,c as o,a2 as i}from"./chunks/framework.CZrxoOIU.js";const b=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"old/qa.md","filePath":"old/qa.md","lastUpdated":1718326650000}'),s={name:"old/qa.md"};function p(r,t,l,d,h,n){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="声明的http接口为什么要继承ihttpapi接口" tabindex="-1">声明的http接口为什么要继承IHttpApi接口？ <a class="header-anchor" href="#声明的http接口为什么要继承ihttpapi接口" aria-label="Permalink to &quot;声明的http接口为什么要继承IHttpApi接口？&quot;">​</a></h2><p>一是为了方便WebApiClient库自动生成接口的代理类，相当用于标记作用；二是继承了<code>IHttpApi</code>接口，http接口代理类实例就有Dispose方法。</p><h2 id="http接口可以继承其它http接口吗" tabindex="-1">http接口可以继承其它http接口吗？ <a class="header-anchor" href="#http接口可以继承其它http接口吗" aria-label="Permalink to &quot;http接口可以继承其它http接口吗？&quot;">​</a></h2><p>可以继承，父接口的相关方法也都当作Api方法，需要注意的是，父接口的方法的接口级特性将失效，而是应用了子接口的接口级特性，所以为了方便理解，最好不要这样继承。</p><h2 id="使用-proxyattribute-host-port-代理特性前-怎么验证代理的有效性" tabindex="-1">使用<code>[ProxyAttribute(host,port)]</code>代理特性前，怎么验证代理的有效性？ <a class="header-anchor" href="#使用-proxyattribute-host-port-代理特性前-怎么验证代理的有效性" aria-label="Permalink to &quot;使用`[ProxyAttribute(host,port)]`代理特性前，怎么验证代理的有效性？&quot;">​</a></h2><p>可以使用ProxyValidator对象的Validate方法来验证代理的有效性。</p><h2 id="为什么不支持将接口方法的返回类型声明为task对象而必须为task-或itask" tabindex="-1">为什么不支持将接口方法的返回类型声明为<code>Task</code>对象而必须为<code>Task&lt;&gt;</code>或<code>ITask&lt;&gt;</code>？ <a class="header-anchor" href="#为什么不支持将接口方法的返回类型声明为task对象而必须为task-或itask" aria-label="Permalink to &quot;为什么不支持将接口方法的返回类型声明为`Task`对象而必须为`Task&lt;&gt;`或`ITask&lt;&gt;`？&quot;">​</a></h2><p>这个是设计的原则，因为不管开发者关不关注返回值，Http请求要么有响应要么抛出异常，如果你不关注结果的解析，可以声明为<code>Task&lt;HttpResponseMessage&gt;</code>而不去解析<code>HttpResponseMessage</code>就可以。</p><h2 id="使用webapiclient怎么下载文件" tabindex="-1">使用WebApiClient怎么下载文件？ <a class="header-anchor" href="#使用webapiclient怎么下载文件" aria-label="Permalink to &quot;使用WebApiClient怎么下载文件？&quot;">​</a></h2><p>你应该将接口返回类型声明为<code>ITask&lt;HttpResponseFile&gt;</code>。</p><h2 id="接口返回类型除了声明为itask-httpresponsemessage-还可以声明哪些抽象的返回类型" tabindex="-1">接口返回类型除了声明为<code>ITask&lt;HttpResponseMessage&gt;</code>，还可以声明哪些抽象的返回类型？ <a class="header-anchor" href="#接口返回类型除了声明为itask-httpresponsemessage-还可以声明哪些抽象的返回类型" aria-label="Permalink to &quot;接口返回类型除了声明为`ITask&lt;HttpResponseMessage&gt;`，还可以声明哪些抽象的返回类型？&quot;">​</a></h2><p>还可以声明为<code>ITask&lt;string&gt;</code>、<code>ITask&lt;Stream&gt;</code>和<code>ITask&lt;Byte[]&gt;</code>，这些都是抽象的返回类型。</p><h2 id="接口声明的参数可以为object或某些类型的基类吗" tabindex="-1">接口声明的参数可以为Object或某些类型的基类吗？ <a class="header-anchor" href="#接口声明的参数可以为object或某些类型的基类吗" aria-label="Permalink to &quot;接口声明的参数可以为Object或某些类型的基类吗？&quot;">​</a></h2><p>可以这样声明，数据还是子类的，但xml序列化会有问题，一般情况下，建议严格按照服务器的具体类型来声明参数。</p><h2 id="webapiclient怎么使用同步请求" tabindex="-1">WebApiClient怎么使用同步请求 <a class="header-anchor" href="#webapiclient怎么使用同步请求" aria-label="Permalink to &quot;WebApiClient怎么使用同步请求&quot;">​</a></h2><p>WebApiClient是对HttpClient的封包，HttpClient没有提供相关的同步请求方法，所以WebApiClient也没有同步请求，不正确的阻塞ITask和Task返回值，在一些环境下很容易死锁。</p>',17)])])}const k=e(s,[["render",p]]);export{b as __pageData,k as default};
